    format: r => `+${(0.04 * r).toFixed(2)}s WINDOW`,
  },
  {
    id: 'blade', name: 'BLADE', glyph: '†', column: 1, row: 2,
    max: 3, costs: [2, 3, 4],
    desc: '+12% melee damage per rank.',
    format: r => `+${12 * r}% MELEE`,
  },
  {
    id: 'arcane', name: 'ARCANE', glyph: '✶', column: 3, row: 1,
    max: 3, costs: [2, 3, 4],
    desc: '+18% spell damage per rank.',
    format: r => `+${18 * r}% SPELL`,
  },
  {
    id: 'flow', name: 'FLOW', glyph: '≋', column: 1, row: 3,
    max: 2, costs: [2, 3],
    desc: '+8% move speed and -12% dash cooldown per rank.',
    format: r => `+${8 * r}% SPEED`,
  },
  {
    id: 'siphon', name: 'SIPHON', glyph: '◉', column: 4, row: 2,
    max: 2, costs: [3, 4],
    desc: 'A successful parry restores +10 health per rank.',
    format: r => `+${10 * r} HP ON PARRY`,
  },
  {
    id: 'ward', name: 'WARD', glyph: '⬡', column: 3, row: 3,
    max: 2, costs: [2, 3],
    desc: '-15% damage taken per rank.',
    format: r => `-${15 * r}% DAMAGE TAKEN`,
  },
]

export function deriveStats(skills = {}) {
  const s = id => Math.max(0, skills[id] || 0)
  return {
    maxHp: 100 + 15 * s('vitality'),
    maxMana: 60 + 15 * s('focus'),
    parryWindow: PARRY.active + 0.04 * s('tempo'),
    parryCooldown: Math.max(0.32, PARRY.cooldown - 0.06 * s('tempo')),
    melee: 1 + 0.12 * s('blade'),
    arcane: 1 + 0.18 * s('arcane'),
    speed: 1 + 0.08 * s('flow'),
    dashCooldown: DASH.cooldown * (1 - 0.12 * s('flow')),
    siphon: 10 * s('siphon'),
    resist: 1 - 0.15 * s('ward'),
  }
}

export function unlockedSpells(highestStage = 1) {
  return SPELL_ORDER.filter(id => SPELLS[id].unlockStage <= Math.max(1, highestStage))
}

export function stageFor(index) {
  if (index < STAGES.length) return STAGES[index]
  const base = STAGES[index % STAGES.length]
  const loop = Math.floor(index / STAGES.length)
  const romans = ['', 'II', 'III', 'IV', 'V', 'VI', 'VII', 'VIII', 'IX', 'X']
  const suffix = romans[Math.min(loop, romans.length - 1)]
  return {
    ...base,
    id: index + 1,
    name: `${base.name} ${suffix}`,
    title: loop === 0 ? base.title : `Ascendant Echo · Cycle ${loop + 1}`,
    hp: Math.round(base.hp * (1 + 0.24 * loop)),
    dmg: base.dmg * (1 + 0.14 * loop),
    boss: base.boss || loop % 5 === 4,
    ascended: loop > 0,
  }
}

export const COMBO_WINDOW = 0.62
export const MAX_HP_TRAIL = 0.55

const KEY = 'spellbreak.save.v1'

export const DEFAULT_SETTINGS = {
  resolution: 'auto',      // auto | sharp | balanced | chunky
  effects: 'high',         // low | medium | high | ultra
  shake: true,
  glow: true,
  scanlines: false,
  reduceFlashes: false,
  fps: '60',               // 60 | 120 | unlimited
  volume: 0.8,
  sfx: 0.9,
  music: 0.45,
}

export function defaultSave() {
  return {
    version: 1,
    stage: 0,              // 0-based index of the next duel
    highestStage: 1,       // highest stage number reached
    runActive: false,
    difficulty: 'medium',
    points: 3,
    skills: {},
    wins: 0,
    losses: 0,
    parries: 0,
    bestCombo: 0,
    totalPoints: 0,
    settings: { ...DEFAULT_SETTINGS },
    seenHelp: false,
    createdAt: Date.now(),
  }
}

function clampNumber(value, min, max, fallback) {
  return Number.isFinite(value) ? Math.max(min, Math.min(max, value)) : fallback
}

export function sanitize(raw) {
  const base = defaultSave()
  if (!raw || typeof raw !== 'object') return base
  const out = { ...base, ...raw }
  out.version = 1
  out.stage = Math.max(0, Math.floor(clampNumber(raw.stage, 0, 9999, 0)))
  out.highestStage = Math.max(1, Math.floor(clampNumber(raw.highestStage, 1, 9999, 1)))
  out.runActive = Boolean(raw.runActive)
  out.difficulty = ['easy', 'medium', 'hard'].includes(raw.difficulty) ? raw.difficulty : 'medium'
  out.points = Math.max(0, Math.floor(clampNumber(raw.points, 0, 9999, 0)))
  out.wins = Math.max(0, Math.floor(clampNumber(raw.wins, 0, 999999, 0)))
  out.losses = Math.max(0, Math.floor(clampNumber(raw.losses, 0, 999999, 0)))
  out.parries = Math.max(0, Math.floor(clampNumber(raw.parries, 0, 999999, 0)))
  out.bestCombo = Math.max(0, Math.floor(clampNumber(raw.bestCombo, 0, 999999, 0)))
  out.totalPoints = Math.max(0, Math.floor(clampNumber(raw.totalPoints, 0, 999999, 0)))
  out.seenHelp = Boolean(raw.seenHelp)
  out.skills = {}
  if (raw.skills && typeof raw.skills === 'object') {
    for (const [key, value] of Object.entries(raw.skills)) {
      if (/^[a-z]+$/.test(key)) out.skills[key] = Math.max(0, Math.min(9, Math.floor(clampNumber(value, 0, 9, 0))))
    }
  }
  out.settings = { ...DEFAULT_SETTINGS, ...(raw.settings && typeof raw.settings === 'object' ? raw.settings : {}) }
  out.settings.resolution = ['auto', 'sharp', 'balanced', 'chunky'].includes(out.settings.resolution) ? out.settings.resolution : 'auto'
  out.settings.effects = ['low', 'medium', 'high', 'ultra'].includes(out.settings.effects) ? out.settings.effects : 'high'
  out.settings.fps = ['60', '120', 'unlimited'].includes(out.settings.fps) ? out.settings.fps : '60'
  out.settings.shake = Boolean(out.settings.shake)
  out.settings.glow = Boolean(out.settings.glow)
  out.settings.scanlines = Boolean(out.settings.scanlines)
  out.settings.reduceFlashes = Boolean(out.settings.reduceFlashes)
  out.settings.volume = clampNumber(Number(out.settings.volume), 0, 1, 0.8)
  out.settings.sfx = clampNumber(Number(out.settings.sfx), 0, 1, 0.9)
  out.settings.music = clampNumber(Number(out.settings.music), 0, 1, 0.45)
  return out
}

export function loadSave() {
  try {
    const raw = localStorage.getItem(KEY)
    if (!raw) return defaultSave()
    return sanitize(JSON.parse(raw))
  } catch {
    return defaultSave()
  }
}

export function writeSave(save) {
  try {
    localStorage.setItem(KEY, JSON.stringify(save))
    return true
  } catch {
    return false
  }
}

export function clearSave() {
  try {
    localStorage.removeItem(KEY)
  } catch { /* ignore */ }
}

export { KEY as SAVE_KEY }

const KEYMAP = {
  ArrowLeft: 'left', KeyA: 'left',
  ArrowRight: 'right', KeyD: 'right',
  ArrowUp: 'jump', KeyW: 'jump', Space: 'jump',
  KeyJ: 'strike', KeyZ: 'strike',
  KeyK: 'heavy', KeyX: 'heavy',
  KeyL: 'parry', KeyC: 'parry',
  ShiftLeft: 'dash', ShiftRight: 'dash',
  KeyS: 'guard', ArrowDown: 'guard',
  Digit1: 'spell1', Numpad1: 'spell1',
  Digit2: 'spell2', Numpad2: 'spell2',
  Digit3: 'spell3', Numpad3: 'spell3',
  Escape: 'pause', KeyP: 'pause',
  Enter: 'confirm',
}

const GAME_KEYS = new Set(Object.keys(KEYMAP))
const BLOCK_DEFAULT = new Set([
  'ArrowLeft', 'ArrowRight', 'ArrowUp', 'ArrowDown', 'Space',
  'ShiftLeft', 'ShiftRight', 'Digit1', 'Digit2', 'Digit3',
])

const ACTIONS = ['left', 'right', 'jump', 'strike', 'heavy', 'parry', 'dash', 'guard', 'spell1', 'spell2', 'spell3', 'pause', 'confirm']

export class Input {
  constructor(target = window) {
    this.target = target
    this.held = new Set()
    this.edges = new Set()
    this.released = new Set()
    this.enabled = true
    this.onFirstInput = null
    this._first = false
    this._down = this._down.bind(this)
    this._up = this._up.bind(this)
    this._blur = this._blur.bind(this)
    target.addEventListener('keydown', this._down, { passive: false })
    target.addEventListener('keyup', this._up)
    target.addEventListener('blur', this._blur)
    this.touchHeld = new Set()
    this.touchEdges = new Set()
  }

  _guard(event) {
    const tag = event.target?.tagName
    return tag === 'INPUT' || tag === 'TEXTAREA' || tag === 'SELECT'
  }

  _down(event) {
    if (this._guard(event)) return
    const action = KEYMAP[event.code]
    if (!action) return
    if (BLOCK_DEFAULT.has(event.code)) event.preventDefault()
    if (!this.enabled) return
    if (!event.repeat && !this.held.has(action)) {
      this.edges.add(action)
      this.touchEdges.add(action)
      if (!this._first) {
        this._first = true
        this.onFirstInput?.()
      }
    }
    this.held.add(action)
  }

  _up(event) {
    const action = KEYMAP[event.code]
    if (!action) return
    this.held.delete(action)
    this.released.add(action)
  }

  _blur() {
    this.held.clear()
    this.touchHeld.clear()
  }

  setTouch(action, down) {
    if (down) {
      if (!this.touchHeld.has(action)) {
        this.touchEdges.add(action)
        if (!this._first) {
          this._first = true
          this.onFirstInput?.()
        }
      }
      this.touchHeld.add(action)
    } else {
      this.touchHeld.delete(action)
    }
  }

  down(action) {
    return this.held.has(action) || this.touchHeld.has(action)
  }

  pressed(action) {
    return this.edges.has(action) || this.touchEdges.has(action)
  }

  releasedNow(action) {
    return this.released.has(action)
  }

  consume(action) {
    this.edges.delete(action)
    this.touchEdges.delete(action)
  }

  endFrame() {
    this.edges.clear()
    this.touchEdges.clear()
    this.released.clear()
  }

  clear() {
    this.held.clear()
    this.touchHeld.clear()
    this.edges.clear()
    this.touchEdges.clear()
    this.released.clear()
  }

  get axis() {
    return (this.down('right') ? 1 : 0) - (this.down('left') ? 1 : 0)
  }

  dispose() {
    this.target.removeEventListener('keydown', this._down)
    this.target.removeEventListener('keyup', this._up)
    this.target.removeEventListener('blur', this._blur)
  }
}

export { KEYMAP, ACTIONS, GAME_KEYS }

