const TAU = Math.PI * 2
const rand = (a, b) => a + Math.random() * (b - a)
const pick = arr => arr[Math.floor(Math.random() * arr.length)]
const clamp = (v, a, b) => Math.max(a, Math.min(b, v))

export const FX_QUALITY = {
  low: { max: 150, scale: 0.45, ambient: 18 },
  medium: { max: 300, scale: 0.7, ambient: 32 },
  high: { max: 540, scale: 1, ambient: 48 },
  ultra: { max: 900, scale: 1.35, ambient: 70 },
}

export class FX {
  constructor() {
    this.particles = []
    this.rings = []
    this.arcs = []
    this.texts = []
    this.bolts = []
    this.sigils = []
    this.flashes = []
    this.ghosts = []
    this.trauma = 0
    this.punch = 0
    this.stopTimer = 0
    this.slowTimer = 0
    this.slowScale = 1
    this.quality = 'high'
    this.glow = true
    this.reduceFlashes = false
    this.time = 0
    this._seed = 0
  }

  setQuality(name) {
    this.quality = FX_QUALITY[name] ? name : 'high'
  }

  get qualityData() {
    return FX_QUALITY[this.quality] || FX_QUALITY.high
  }

  reset() {
    this.particles.length = 0
    this.rings.length = 0
    this.arcs.length = 0
    this.texts.length = 0
    this.bolts.length = 0
    this.sigils.length = 0
    this.flashes.length = 0
    this.ghosts.length = 0
    this.trauma = 0
    this.punch = 0
    this.stopTimer = 0
    this.slowTimer = 0
    this.slowScale = 1
  }

  particle(options) {
    const q = this.qualityData
    if (this.particles.length >= q.max) this.particles.shift()
    const life = options.life ?? 0.6
    this.particles.push({
      x: options.x, y: options.y,
      vx: options.vx ?? 0, vy: options.vy ?? 0,
      life, max: life,
      size: (options.size ?? 1.4) * (options.unscaled ? 1 : q.scale),
      color: options.color ?? '#ffffff',
      glow: options.glow ?? true,
      gravity: options.gravity ?? 0,
      drag: options.drag ?? 1.5,
      shape: options.shape ?? 'spark',
      rot: options.rot ?? 0,
      vr: options.vr ?? 0,
      fade: options.fade ?? 'ease',
      alpha: options.alpha ?? 1,
    })
  }

  burst(x, y, options = {}) {
    const q = this.qualityData
    const count = Math.max(1, Math.round((options.count ?? 12) * q.scale))
    const colors = options.colors ?? ['#ffffff']
    const angle = options.angle ?? 0
    const spread = options.spread ?? TAU
    const speed = options.speed ?? 90
    const size = options.size ?? 1.5
    const life = options.life ?? 0.45
    for (let i = 0; i < count; i++) {
      const a = angle + (spread === TAU ? rand(0, TAU) : rand(-spread / 2, spread / 2))
      const v = speed * rand(0.25, 1)
      this.particle({
        x: x + rand(-2, 2), y: y + rand(-2, 2),
        vx: Math.cos(a) * v, vy: Math.sin(a) * v,
        life: life * rand(0.55, 1.25),
        size: size * rand(0.6, 1.5),
        color: pick(colors),
        gravity: options.gravity ?? 120,
        drag: options.drag ?? 2.2,
        shape: options.shape ?? 'spark',
        glow: options.glow ?? true,
      })
    }
  }

  sparks(x, y, color, count = 10, speed = 120, angle = 0, spread = TAU) {
    this.burst(x, y, {
      count, speed, angle, spread,
      colors: [color, '#ffffff', color],
      size: 1.3, life: 0.42, gravity: 260, drag: 1.2,
    })
  }

  impact(x, y, color, power = 1) {
    const q = this.qualityData
    this.ring(x, y, {
      radius: 2, radiusEnd: 22 + power * 10,
      life: 0.32, width: 2.2, color, squash: 0.7,
    })
    this.burst(x, y, {
      count: Math.round(10 + 10 * power),
      speed: 80 + 70 * power,
      colors: [color, '#ffffff'],
      size: 1.4 + power * 0.4,
      life: 0.4 + power * 0.15,
      gravity: 200,
    })
    this.shake(0.18 * power)
    this.punch = Math.max(this.punch, 0.006 * power)
  }

  ring(x, y, options = {}) {
    const life = options.life ?? 0.4
    this.rings.push({
      x, y,
      radius: options.radius ?? 4,
      radiusEnd: options.radiusEnd ?? 40,
      life, max: life,
      width: options.width ?? 2,
      color: options.color ?? '#ffffff',
      glow: options.glow ?? true,
      squash: options.squash ?? 1,
      alpha: options.alpha ?? 1,
      easing: options.easing ?? 'out',
      delay: options.delay ?? 0,
    })
  }

  column(x, y, color, height = 120, width = 5) {
    this.ring(x, y, { radius: 1, radiusEnd: width, radiusEnd: width, life: 0.28, width: height, color, squash: 0.1, alpha: 0.7 })
  }

  slashArc(x, y, from, to, radius, color, options = {}) {
    this.arcs.push({
      x, y, from, to, radius,
      life: options.life ?? 0.2, max: options.life ?? 0.2,
      color,
      width: options.width ?? 3,
      alpha: options.alpha ?? 0.9,
    })
  }

  text(x, y, value, color = '#ffffff', options = {}) {
    const life = options.life ?? 0.72
    this.texts.push({
      x, y, value, color,
      life, max: life,
      size: options.size ?? 9,
      vy: options.vy ?? -34,
      vx: options.vx ?? 0,
      weight: options.weight ?? 'bold',
      glow: options.glow ?? true,
    })
  }

  bolt(x, fromY, toY, color = '#e8dcff', options = {}) {
    const points = [{ x, y: fromY }]
    let cx = x
    let cy = fromY
    const segments = 9
    for (let i = 1; i < segments; i++) {
      const p = i / segments
      cx = x + rand(-1, 1) * (1 - p) * 26
      cy = fromY + (toY - fromY) * p
      points.push({ x: cx, y: cy })
    }
    points.push({ x: x + rand(-2, 2), y: toY })
    const branches = []
    for (let i = 1; i < segments - 1; i++) {
      if (Math.random() > 0.42) continue
      const length = rand(8, 26) * (options.power ?? 1)
      const dir = Math.random() > 0.5 ? 1 : -1
      branches.push([
        points[i],
        { x: points[i].x + dir * length * 0.6, y: points[i].y + length * 0.4 },
        { x: points[i].x + dir * length, y: points[i].y + length * 0.55 },
      ])
    }
    this.bolts.push({
      points, branches,
      life: options.life ?? 0.24, max: options.life ?? 0.24,
      color, width: options.width ?? 3,
    })
  }

  sigil(x, y, color, options = {}) {
    const life = options.life ?? 0.7
    this.sigils.push({
      x, y,
      radius: options.radius ?? 26,
      life, max: life,
      color,
      rot: options.rot ?? rand(0, TAU),
      spin: options.spin ?? 3,
      squash: options.squash ?? 0.3,
      grow: options.grow ?? true,
      alpha: options.alpha ?? 0.8,
    })
  }

  ghost(snapshot, color, life = 0.24) {
    const q = this.qualityData
    if (this.ghosts.length > q.max / 6) this.ghosts.shift()
    this.ghosts.push({ ...snapshot, color, life, max: life })
  }

  flash(color = '#ffffff', alpha = 0.5) {
    if (this.reduceFlashes) alpha *= 0.35
    this.flashes.push({ color, alpha, life: 0.16, max: 0.16 })
  }

  shake(amount) {
    this.trauma = clamp(this.trauma + amount, 0, 1)
  }

  stop(seconds) {
    this.stopTimer = Math.max(this.stopTimer, seconds)
  }

  slow(scale, seconds) {
    this.slowScale = scale
    this.slowTimer = Math.max(this.slowTimer, seconds)
  }

  get frozen() {
    return this.stopTimer > 0
  }

  get timeScale() {
    if (this.stopTimer > 0) return 0.015
    if (this.slowTimer > 0) return this.slowScale
    return 1
  }

  shakeOffset() {
    const power = this.trauma * this.trauma * 9
    return {
      x: rand(-power, power),
      y: rand(-power, power * 0.8),
    }
  }

  update(dt, realDt = dt) {
    this.time += realDt
    this.stopTimer = Math.max(0, this.stopTimer - realDt)
    this.slowTimer = Math.max(0, this.slowTimer - realDt)
    this.trauma = Math.max(0, this.trauma - realDt * 1.5)
    this.punch = Math.max(0, this.punch - realDt * 0.055)

    const s = this.stopTimer > 0 ? dt * 0.08 : dt
    if (s <= 0) return

    for (let i = this.particles.length - 1; i >= 0; i--) {
      const p = this.particles[i]
      p.life -= s
      if (p.life <= 0) { this.particles.splice(i, 1); continue }
      p.vx -= p.vx * p.drag * s
      p.vy -= p.vy * p.drag * s * 0.25
      p.vy += p.gravity * s
      p.x += p.vx * s
      p.y += p.vy * s
      p.rot += p.vr * s
    }
    for (let i = this.rings.length - 1; i >= 0; i--) {
      const r = this.rings[i]
      if (r.delay > 0) { r.delay -= s; continue }
      r.life -= s
      if (r.life <= 0) this.rings.splice(i, 1)
    }
    for (let i = this.arcs.length - 1; i >= 0; i--) {
      const a = this.arcs[i]
      a.life -= s
      if (a.life <= 0) this.arcs.splice(i, 1)
    }
    for (let i = this.texts.length - 1; i >= 0; i--) {
      const t = this.texts[i]
      t.life -= realDt
      if (t.life <= 0) { this.texts.splice(i, 1); continue }
      t.y += t.vy * realDt
      t.x += t.vx * realDt
      t.vy += 28 * realDt
    }
    for (let i = this.bolts.length - 1; i >= 0; i--) {
      const b = this.bolts[i]
      b.life -= s
      if (b.life <= 0) this.bolts.splice(i, 1)
    }
    for (let i = this.sigils.length - 1; i >= 0; i--) {
      const g = this.sigils[i]
      g.life -= s
      g.rot += g.spin * s
      if (g.life <= 0) this.sigils.splice(i, 1)
    }
    for (let i = this.flashes.length - 1; i >= 0; i--) {
      const f = this.flashes[i]
      f.life -= realDt
      if (f.life <= 0) this.flashes.splice(i, 1)
    }
    for (let i = this.ghosts.length - 1; i >= 0; i--) {
      const g = this.ghosts[i]
      g.life -= s
      if (g.life <= 0) this.ghosts.splice(i, 1)
    }
  }

  render(ctx, cam) {
    ctx.save()
    ctx.globalCompositeOperation = 'lighter'

    // ground sigils
    for (const s of this.sigils) {
      const t = 1 - s.life / s.max
      const alpha = s.alpha * (1 - t) * (0.4 + 0.6 * Math.sin(t * Math.PI))
      const radius = s.radius * (s.grow ? 0.5 + t * 1.4 : 1)
      this._ellipseRune(ctx, cam.X(s.x), cam.Y(s.y), radius * cam.scale, radius * s.squash * cam.scale, s.rot, s.color, alpha, 1.5)
    }

    // arcs / slash trails
    for (const a of this.arcs) {
      const t = 1 - a.life / a.max
      const alpha = a.alpha * (1 - t) * 0.9
      const steps = 13
      for (let i = 0; i < steps; i++) {
        const p = i / (steps - 1)
        const ang = a.from + (a.to - a.from) * p
        const rr = a.radius * (0.82 + 0.18 * p)
        const x = cam.X(a.x + Math.cos(ang) * rr)
        const y = cam.Y(a.y + Math.sin(ang) * rr)
        const w = Math.max(1, a.width * cam.scale * (0.4 + 0.6 * Math.sin(p * Math.PI)))
        if (this.glow) {
          ctx.globalAlpha = alpha * 0.26
          ctx.fillStyle = a.color
          ctx.fillRect(x - w * 2, y - w * 2, w * 4, w * 4)
        }
        ctx.globalAlpha = alpha * (0.5 + 0.5 * Math.sin(p * Math.PI))
        ctx.fillStyle = i % 3 === 0 ? '#ffffff' : a.color
        ctx.fillRect(x - w / 2, y - w / 2, w, w)
      }
    }

    // rings
    for (const r of this.rings) {
      if (r.delay > 0) continue
      const t = 1 - r.life / r.max
      const e = 1 - Math.pow(1 - t, 3)
      const radius = r.radius + (r.radiusEnd - r.radius) * e
      const alpha = r.alpha * (1 - t) * 0.85
      const x = cam.X(r.x)
      const y = cam.Y(r.y)
      const rx = Math.max(0.6, radius * cam.scale)
      const ry = Math.max(0.6, radius * r.squash * cam.scale)
      ctx.globalAlpha = alpha
      ctx.strokeStyle = r.color
      ctx.lineWidth = Math.max(1, r.width * cam.scale * (1 - t * 0.6))
      ctx.beginPath()
      ctx.ellipse(x, y, rx, ry, 0, 0, TAU)
      ctx.stroke()
      if (this.glow) {
        ctx.globalAlpha = alpha * 0.25
        ctx.lineWidth *= 3.4
        ctx.stroke()
      }
    }

    // bolts
    for (const b of this.bolts) {
      const t = 1 - b.life / b.max
      const alpha = Math.sin((1 - t) * Math.PI) * 0.95
      const jitterX = t < 0.6 ? rand(-2, 2) : 0
      for (let pass = 0; pass < 2; pass++) {
        ctx.globalAlpha = pass === 0 ? alpha * 0.28 : alpha
        ctx.strokeStyle = pass === 0 ? b.color : '#ffffff'
        ctx.lineWidth = (pass === 0 ? b.width * 3 : b.width) * cam.scale
        ctx.beginPath()
        b.points.forEach((p, i) => {
          const x = cam.X(p.x + jitterX * (pass + 1))
          const y = cam.Y(p.y)
          if (i === 0) ctx.moveTo(x, y)
          else ctx.lineTo(x, y)
        })
        ctx.stroke()
        for (const branch of b.branches) {
          ctx.beginPath()
          branch.forEach((p, i) => {
            const x = cam.X(p.x)
            const y = cam.Y(p.y)
            if (i === 0) ctx.moveTo(x, y)
            else ctx.lineTo(x, y)
          })
          ctx.stroke()
        }
      }
    }

    // particles
    for (const p of this.particles) {
      const t = 1 - p.life / p.max
      const alpha = p.alpha * (p.fade === 'ease' ? Math.pow(1 - t, 1.3) : 1 - t)
      if (alpha <= 0.01) continue
      const x = cam.X(p.x)
      const y = cam.Y(p.y)
      const size = Math.max(1, p.size * cam.scale)
      ctx.globalAlpha = alpha
      ctx.fillStyle = p.color
      if (p.shape === 'spark' && (Math.abs(p.vx) + Math.abs(p.vy)) > 10) {
        const vx = p.vx * 0.012 * cam.scale
        const vy = p.vy * 0.012 * cam.scale
        if (this.glow && p.glow) {
          ctx.globalAlpha = alpha * 0.25
          ctx.fillRect(x + vx * 0.5 - 1, y + vy * 0.5 - 1, size * 2.6, size * 2.6)
          ctx.globalAlpha = alpha
        }
        ctx.fillRect(x - Math.abs(vx) / 2, y - Math.abs(vy) / 2, Math.max(1, Math.abs(vx)), Math.max(1, Math.abs(vy)))
      } else if (p.shape === 'shard') {
        ctx.save()
        ctx.translate(x, y)
        ctx.rotate(p.rot)
        ctx.fillRect(-size / 2, -size / 2, size, size * 0.45)
        ctx.restore()
      } else {
        const s = p.shape === 'smoke' ? size * 2.6 : size
        if (this.glow && p.glow) {
          ctx.globalAlpha = alpha * 0.22
          ctx.fillRect(x - s * 1.5, y - s * 1.5, s * 3, s * 3)
          ctx.globalAlpha = alpha
        }
        ctx.fillRect(x - s / 2, y - s / 2, s, s)
      }
    }
    ctx.restore()

    // soft-textured smoke (normal blend) drawn after
    ctx.save()
    for (const p of this.particles) {
      if (p.shape !== 'smoke') continue
      const t = 1 - p.life / p.max
      ctx.globalAlpha = p.alpha * (1 - t) * 0.22
      ctx.fillStyle = p.color
      const x = cam.X(p.x)
      const y = cam.Y(p.y)
      const size = p.size * cam.scale * (1 + t * 2)
      ctx.beginPath()
      ctx.arc(x, y, Math.max(1, size), 0, TAU)
      ctx.fill()
    }
    ctx.restore()

    // floating text
    this._texts(ctx, cam)
  }

  _texts(ctx, cam) {
    if (!this.texts.length) return
    ctx.save()
    ctx.textAlign = 'center'
    ctx.textBaseline = 'middle'
    for (const t of this.texts) {
      const p = 1 - t.life / t.max
      const alpha = p < 0.12 ? p / 0.12 : Math.pow(1 - (p - 0.12) / 0.88, 0.8)
      const size = Math.max(7, Math.round(t.size * cam.scale * (1 + Math.sin(Math.min(1, p * 2.4) * Math.PI) * 0.16)))
      ctx.font = `${t.weight === 'bold' ? '700 ' : ''}${size}px Silkscreen, "Courier New", monospace`
      const x = Math.round(cam.X(t.x))
      const y = Math.round(cam.Y(t.y))
      ctx.globalAlpha = alpha * 0.9
      ctx.fillStyle = 'rgba(4,4,10,0.85)'
      ctx.fillText(t.value, x + 1, y + 1)
      ctx.globalAlpha = alpha
      ctx.fillStyle = t.color
      if (this.glow) {
        ctx.globalAlpha = alpha * 0.35
        ctx.fillText(t.value, x, y)
        ctx.globalAlpha = alpha
      }
      ctx.fillText(t.value, x, y)
    }
    ctx.restore()
  }

  _ellipseRune(ctx, x, y, rx, ry, rot, color, alpha, width) {
    ctx.save()
    ctx.globalAlpha = alpha
    ctx.strokeStyle = color
    ctx.lineWidth = Math.max(1, width * 0.9)
    ctx.beginPath()
    ctx.ellipse(x, y, rx, ry, 0, 0, TAU)
    ctx.stroke()
    ctx.globalAlpha = alpha * 0.55
    ctx.beginPath()
    ctx.ellipse(x, y, rx * 0.72, ry * 0.72, 0, 0, TAU)
    ctx.stroke()
    for (let i = 0; i < 8; i++) {
      const a = rot + (i / 8) * TAU
      const ix = x + Math.cos(a) * rx * 0.86
      const iy = y + Math.sin(a) * ry * 0.86
      ctx.fillStyle = i % 2 ? color : '#ffffff'
      ctx.fillRect(ix - 1, iy - 1, 2, 2)
    }
    ctx.restore()
  }

  renderScreen(ctx, width, height) {
    for (const f of this.flashes) {
      const p = f.life / f.max
      ctx.globalAlpha = f.alpha * p
      ctx.fillStyle = f.color
      ctx.fillRect(0, 0, width, height)
    }
    ctx.globalAlpha = 1
  }

  renderGhosts(ctx, cam, drawGhost) {
    for (const g of this.ghosts) {
      const alpha = (g.life / g.max) * 0.5
      drawGhost(ctx, cam, g, g.color, alpha)
    }
  }
}

// Procedural pixel-art renderer: arena, parallax sky, duelists.
const TAU = Math.PI * 2
const clamp = (v, a, b) => Math.max(a, Math.min(b, v))
const rnd = (a, b) => a + Math.random() * (b - a)

const bg = { key: '', stars: [], mountains: [], dust: [] }
let lastPalette = null

function ensureBackground(w, h) {
  const key = `${w}x${h}`
  if (bg.key === key) return
  bg.key = key
  bg.stars = Array.from({ length: Math.round(w * h / 5200) }, () => ({
    x: Math.random() * w * 1.4 - w * 0.2,
    y: Math.random() * h * 0.72,
    r: Math.random() < 0.82 ? 1 : 2,
    p: Math.random() * TAU,
    s: 0.6 + Math.random() * 1.6,
    c: Math.random() < 0.15 ? '#9fe8ff' : Math.random() < 0.1 ? '#ffc4ef' : '#d8dcff',
  }))
  const layer = (amp, base) => {
    const points = []
    const span = w * 1.5
    const step = Math.max(14, w / 26)
    for (let x = -w * 0.25; x <= span; x += step) {
      points.push({ x, y: base + Math.sin(x * 0.021 + amp) * amp + Math.sin(x * 0.007 - amp * 2) * amp * 1.3 })
    }
    return points
  }
  bg.mountains = [
    { points: layer(22, h * 0.56), color: '#141128', par: 0.04, edge: '#1e1940' },
    { points: layer(30, h * 0.63), color: '#0e0b1e', par: 0.08, edge: '#181333' },
    { points: layer(18, h * 0.7), color: '#080714', par: 0.13, edge: '#120f24' },
  ]
  bg.dust = Array.from({ length: 22 }, () => ({
    x: Math.random() * w,
    y: Math.random() * h,
    r: Math.random() < 0.7 ? 1 : 2,
    sp: 2 + Math.random() * 7,
    p: Math.random() * TAU,
  }))
}

function px(ctx, x, y, w, h, color) {
  ctx.fillStyle = color
  ctx.fillRect(Math.round(x), Math.round(y), Math.max(1, Math.round(w)), Math.max(1, Math.round(h)))
}

function pline(ctx, x1, y1, x2, y2, width, color) {
  const steps = Math.max(2, Math.ceil(Math.max(Math.abs(x2 - x1), Math.abs(y2 - y1)) / Math.max(1, width * 0.6)))
  ctx.fillStyle = color
  for (let i = 0; i <= steps; i++) {
    const t = i / steps
    const x = Math.round(x1 + (x2 - x1) * t - width / 2)
    const y = Math.round(y1 + (y2 - y1) * t - width / 2)
    ctx.fillRect(x, y, Math.max(1, Math.round(width)), Math.max(1, Math.round(width)))
  }
}

function glowDot(ctx, x, y, r, color, alpha) {
  ctx.save()
  ctx.globalCompositeOperation = 'lighter'
  ctx.globalAlpha = alpha
  ctx.fillStyle = color
  ctx.beginPath()
  ctx.arc(x, y, r, 0, TAU)
  ctx.fill()
  ctx.restore()
}

// ------------------------------------------------------------------ sky

export function drawSky(ctx, cam, time, palette, settings, stage) {
  const w = cam.width
  const h = cam.height
  ensureBackground(w, h)
  const accent = stage?.accent || palette.trim

  const sky = ctx.createLinearGradient(0, 0, 0, h)
  sky.addColorStop(0, '#04040c')
  sky.addColorStop(0.38, '#080813')
  sky.addColorStop(0.64, '#0f0b20')
  sky.addColorStop(1, '#070610')
  ctx.fillStyle = sky
  ctx.fillRect(0, 0, w, h)

  // aurora veil
  ctx.save()
  ctx.globalCompositeOperation = 'lighter'
  const aurora = ctx.createRadialGradient(w * 0.52, h * 0.38, 0, w * 0.52, h * 0.38, w * 0.72)
  aurora.addColorStop(0, hexA(accent, 0.05))
  aurora.addColorStop(0.5, hexA(accent, 0.025))
  aurora.addColorStop(1, 'rgba(0,0,0,0)')
  ctx.fillStyle = aurora
  ctx.fillRect(0, 0, w, h)
  ctx.restore()

  // stars
  const drift = -cam.x * 0.02
  for (const st of bg.stars) {
    const tw = 0.45 + 0.55 * Math.abs(Math.sin(time * st.s + st.p))
    if (tw < 0.35) continue
    ctx.globalAlpha = tw * 0.9
    px(ctx, ((st.x + drift) % (w * 1.4) + w * 1.4) % (w * 1.4) - w * 0.2, st.y - cam.y * 0.004, st.r, st.r, st.c)
  }
  ctx.globalAlpha = 1

  // moon
  const moonX = w * 0.74 - cam.x * 0.035
  const moonY = h * 0.24
  const moonR = Math.min(w, h) * 0.155
  const halo = ctx.createRadialGradient(moonX, moonY, moonR * 0.6, moonX, moonY, moonR * 2.9)
  halo.addColorStop(0, hexA(accent, 0.18))
  halo.addColorStop(0.4, hexA(accent, 0.06))
  halo.addColorStop(1, 'rgba(0,0,0,0)')
  ctx.fillStyle = halo
  ctx.fillRect(moonX - moonR * 3, moonY - moonR * 3, moonR * 6, moonR * 6)

  ctx.fillStyle = '#e7e2ff'
  ctx.beginPath()
  ctx.arc(moonX, moonY, moonR, 0, TAU)
  ctx.fill()
  ctx.fillStyle = '#c9c2ea'
  ctx.beginPath()
  ctx.arc(moonX + moonR * 0.16, moonY + moonR * 0.12, moonR * 0.92, 0, TAU)
  ctx.fill()
  ctx.fillStyle = '#d8d2f3'
  ctx.beginPath()
  ctx.arc(moonX - moonR * 0.1, moonY - moonR * 0.06, moonR * 0.75, 0, TAU)
  ctx.fill()
  ctx.fillStyle = 'rgba(150,140,190,0.28)'
  for (const [cx, cy, cr] of [[-0.3, -0.18, 0.16], [0.18, 0.32, 0.12], [0.32, -0.34, 0.09], [-0.05, 0.48, 0.07], [-0.5, 0.3, 0.1]]) {
    ctx.beginPath()
    ctx.arc(moonX + moonR * cx, moonY + moonR * cy, moonR * cr, 0, TAU)
    ctx.fill()
  }
  // eclipse shadow for boss stages
  if (stage?.eclipse) {
    ctx.fillStyle = 'rgba(6,4,14,0.92)'
    ctx.beginPath()
    ctx.arc(moonX + moonR * 0.42, moonY - moonR * 0.2, moonR * 0.98, 0, TAU)
    ctx.fill()
    ctx.strokeStyle = hexA(accent, 0.5)
    ctx.lineWidth = Math.max(1, moonR * 0.045)
    ctx.beginPath()
    ctx.arc(moonX + moonR * 0.42, moonY - moonR * 0.2, moonR * 0.98, 0, TAU)
    ctx.stroke()
  }

  // mountains
  for (const layer of bg.mountains) {
    ctx.fillStyle = layer.color
    ctx.beginPath()
    let first = true
    for (const p of layer.points) {
      const x = p.x - cam.x * layer.par
      const y = p.y
      if (first) { ctx.moveTo(x, h); ctx.lineTo(x, y); first = false }
      else ctx.lineTo(x, y)
    }
    ctx.lineTo(w + w * 0.4, h)
    ctx.closePath()
    ctx.fill()
    ctx.strokeStyle = hexA(layer.edge, 0.4)
    ctx.lineWidth = 1
    ctx.stroke()
  }

  // distant shrine spires
  ctx.save()
  const par = -cam.x * 0.16
  for (const [sx, sh, sw] of [[w * 0.16, h * 0.16, 7], [w * 0.55, h * 0.1, 5], [w * 0.86, h * 0.19, 8]]) {
    const base = h * 0.66
    const x = sx + par
    ctx.fillStyle = '#0b0917'
    ctx.beginPath()
    ctx.moveTo(x - sw, base)
    ctx.lineTo(x - sw * 0.4, base - sh)
    ctx.lineTo(x, base - sh - 6)
    ctx.lineTo(x + sw * 0.4, base - sh)
    ctx.lineTo(x + sw, base)
    ctx.closePath()
    ctx.fill()
    ctx.globalCompositeOperation = 'lighter'
    ctx.globalAlpha = 0.5 + 0.3 * Math.sin(time * 1.4 + sx)
    glowDot(ctx, x, base - sh - 4, 2.2, accent, 0.65)
    ctx.globalCompositeOperation = 'source-over'
    ctx.globalAlpha = 1
  }
  ctx.restore()

  // horizon mist
  const mist = ctx.createLinearGradient(0, h * 0.55, 0, h * 0.84)
  mist.addColorStop(0, 'rgba(20,16,42,0)')
  mist.addColorStop(0.55, hexA(accent, 0.055))
  mist.addColorStop(1, 'rgba(8,6,16,0)')
  ctx.fillStyle = mist
  ctx.fillRect(0, h * 0.5, w, h * 0.4)

  // drifting dust
  for (const d of bg.dust) {
    const x = (d.x + time * d.sp * 0.4 + Math.sin(time * 0.4 + d.p) * 6 - cam.x * 0.05) % w
    ctx.globalAlpha = 0.12 + 0.16 * Math.abs(Math.sin(time * 0.8 + d.p))
    px(ctx, x < 0 ? x + w : x, d.y + Math.sin(time * 0.9 + d.p) * 4, d.r, d.r, accent)
  }
  ctx.globalAlpha = 1
}

// --------------------------------------------------------------- arena

export function drawPlatform(ctx, cam, time, palette, stage) {
  const y = cam.Y(0)
  const x0 = cam.X(-ARENA_HALF - 24)
  const x1 = cam.X(ARENA_HALF + 24)
  const w = x1 - x0
  const depth = ARENA_DEPTH * cam.scale
  const accent = stage?.accent || palette.trim

  // under-glow
  ctx.save()
  ctx.globalCompositeOperation = 'lighter'
  const glow = ctx.createRadialGradient((x0 + x1) / 2, y + depth * 0.4, 0, (x0 + x1) / 2, y + depth * 0.4, w * 0.5)
  glow.addColorStop(0, hexA(accent, 0.14))
  glow.addColorStop(0.6, hexA(accent, 0.045))
  glow.addColorStop(1, 'rgba(0,0,0,0)')
  ctx.fillStyle = glow
  ctx.beginPath()
  ctx.ellipse((x0 + x1) / 2, y + depth * 0.45, w * 0.5, depth * 1.2, 0, 0, TAU)
  ctx.fill()
  ctx.restore()

  // rocky underside
  const under = ctx.createLinearGradient(0, y, 0, y + depth * 2.4)
  under.addColorStop(0, '#10101e')
  under.addColorStop(0.5, '#0a0914')
  under.addColorStop(1, 'rgba(5,4,10,0)')
  ctx.fillStyle = under
  ctx.beginPath()
  ctx.moveTo(x0 - 4, y)
  ctx.lineTo(x0 + w * 0.06, y + depth * 1.6)
  ctx.lineTo(x0 + w * 0.2, y + depth * 1.05)
  ctx.lineTo(x0 + w * 0.33, y + depth * 2.1)
  ctx.lineTo(x0 + w * 0.48, y + depth * 1.2)
  ctx.lineTo(x0 + w * 0.62, y + depth * 2.3)
  ctx.lineTo(x0 + w * 0.78, y + depth * 1.1)
  ctx.lineTo(x0 + w * 0.9, y + depth * 1.7)
  ctx.lineTo(x1 + 4, y)
  ctx.closePath()
  ctx.fill()

  // front face layers
  ctx.fillStyle = '#0d0c18'
  ctx.fillRect(x0, y, w, depth)
  ctx.fillStyle = '#121022'
  ctx.fillRect(x0 + 2, y + 1, w - 4, depth * 0.5)
  ctx.fillStyle = '#090812'
  ctx.fillRect(x0, y + depth * 0.62, w, depth * 0.38)

  // cracks
  ctx.strokeStyle = 'rgba(90,84,140,0.22)'
  ctx.lineWidth = 1
  for (let i = 0; i < 7; i++) {
    const cx = x0 + (i + 0.5) * (w / 7)
    ctx.beginPath()
    ctx.moveTo(cx, y + 2)
    ctx.lineTo(cx + (i % 2 ? 3 : -4), y + depth * 0.55)
    ctx.lineTo(cx + (i % 2 ? -1 : 2), y + depth * 0.95)
    ctx.stroke()
  }

  // top edge
  ctx.fillStyle = '#24213d'
  ctx.fillRect(x0 - 1, y - 2, w + 2, 3)
  ctx.fillStyle = hexA(accent, 0.7)
  ctx.fillRect(x0 + w * 0.06, y - 2, w * 0.88, 1)
  ctx.fillStyle = 'rgba(255,255,255,0.1)'
  ctx.fillRect(x0, y + 1, w, 1)

  // edge pillars
  for (const dir of [-1, 1]) {
    const ex = cam.X(dir * (ARENA_HALF + 6))
    ctx.fillStyle = '#16142a'
    ctx.fillRect(ex - 3, y - 16 * cam.scale, 6, 16 * cam.scale)
    ctx.fillStyle = hexA(accent, 0.85)
    ctx.fillRect(ex - 1, y - 18 * cam.scale, 2, 3)
    ctx.globalCompositeOperation = 'lighter'
    glowDot(ctx, ex, y - 18 * cam.scale, 5 * cam.scale, accent, 0.12 + 0.05 * Math.sin(time * 2 + dir))
    ctx.globalCompositeOperation = 'source-over'
  }

  // central arena sigil
  ctx.save()
  ctx.translate(cam.X(0), y + depth * 0.42)
  const rx = 42 * cam.scale
  const ry = 9 * cam.scale
  ctx.strokeStyle = hexA(accent, 0.28)
  ctx.lineWidth = 1
  ctx.beginPath()
  ctx.ellipse(0, 0, rx, ry, 0, 0, TAU)
  ctx.stroke()
  ctx.beginPath()
  ctx.ellipse(0, 0, rx * 0.62, ry * 0.62, 0, 0, TAU)
  ctx.stroke()
  for (let i = 0; i < 12; i++) {
    const a = (i / 12) * TAU + time * 0.14
    const gx = Math.cos(a) * rx * 0.82
    const gy = Math.sin(a) * ry * 0.82
    ctx.fillStyle = hexA(accent, i % 3 === 0 ? 0.65 : 0.28)
    ctx.fillRect(gx, gy, 1, 1)
  }
  ctx.restore()

  // hanging chains
  ctx.strokeStyle = 'rgba(52,48,84,0.55)'
  for (const dir of [-1, 1]) {
    const cx = cam.X(dir * 118)
    ctx.beginPath()
    ctx.moveTo(cx, y + depth)
    for (let i = 0; i < 6; i++) {
      const sway = Math.sin(time * 0.8 + i * 0.7 + dir) * i * 0.6
      ctx.lineTo(cx + sway, y + depth + (i + 1) * 4 * cam.scale)
    }
    ctx.stroke()
  }

  // foreground haze
  const fog = ctx.createLinearGradient(0, y - 8 * cam.scale, 0, y + depth * 2.2)
  fog.addColorStop(0, 'rgba(10,8,20,0)')
  fog.addColorStop(0.5, 'rgba(26,22,52,0.18)')
  fog.addColorStop(1, 'rgba(6,5,12,0)')
  ctx.fillStyle = fog
  ctx.fillRect(x0, y - 8 * cam.scale, w, depth * 2.2)

  // drifting floor energy
  ctx.save()
  ctx.globalCompositeOperation = 'lighter'
  for (let i = 0; i < 5; i++) {
    const fx = cam.X(-150 + ((time * 14 + i * 60) % 300))
    ctx.globalAlpha = 0.06 + 0.05 * Math.sin(time * 1.5 + i)
    px(ctx, fx, y + 1, 10 * cam.scale, 1, accent)
  }
  ctx.restore()
}

// --------------------------------------------------------------- duelist

const POSES = {
  idle: { hand: [5, -19], blade: -0.48, lean: 0, crouch: 0 },
  strike1: { hand: [11, -23], blade: -0.05, lean: 1.2, crouch: 0 },
  strike2: { hand: [11, -19], blade: 0.35, lean: 1.4, crouch: 0 },
  strike3: { hand: [12, -24], blade: 0.15, lean: 1.8, crouch: 0 },
  heavy: { hand: [11, -17], blade: 0.85, lean: 2.2, crouch: 0.6 },
  parry: { hand: [7, -22], blade: -Math.PI / 2 - 0.2, lean: -0.8, crouch: 0.8 },
  cast: { hand: [11, -22], blade: -1.2, lean: -0.6, crouch: 0.3 },
  guard: { hand: [8, -20], blade: 0, lean: -1.4, crouch: 1.2 },
  hurt: { hand: [2, -15], blade: 1.2, lean: -2.6, crouch: 0.4 },
  stagger: { hand: [0, -13], blade: 1.5, lean: -3, crouch: 1.8 },
  dash: { hand: [7, -21], blade: 0.2, lean: 2.6, crouch: 0.5 },
  dead: { hand: [3, -14], blade: 1.4, lean: -4, crouch: 3 },
}

function blendPose(a, b, t) {
  return {
    hand: [a.hand[0] + (b.hand[0] - a.hand[0]) * t, a.hand[1] + (b.hand[1] - a.hand[1]) * t],
    blade: a.blade + (b.blade - a.blade) * t,
    lean: a.lean + (b.lean - a.lean) * t,
    crouch: a.crouch + (b.crouch - a.crouch) * t,
  }
}

function actionPose(f) {
  const t = f.actionT || 0
  const dur = f.actionDur || 1
  const p = clamp(t / dur, 0, 1)
  const base = POSES[f.drawPose || 'idle'] || POSES.idle
  const target = POSES[f.action] || POSES.idle
  if (f.action === 'strike1' || f.action === 'strike2' || f.action === 'strike3' || f.action === 'heavy') {
    if (p < 0.42) return blendPose(base, { ...target, hand: [-4, -27], blade: -2.5, lean: -1.2, crouch: target.crouch * 0.4 }, p / 0.42)
    if (p < 0.62) return blendPose({ ...target, hand: [-4, -27], blade: -2.5, lean: -1.2, crouch: target.crouch * 0.4 }, target, (p - 0.42) / 0.2)
    return blendPose(target, POSES.idle, Math.min(1, (p - 0.62) / 0.38))
  }
  if (f.action === 'cast') {
    if (p < 0.5) return blendPose(base, target, p / 0.5)
    return blendPose(target, POSES.idle, (p - 0.5) / 0.5)
  }
  if (f.action === 'parry') {
    if (p < 0.18) return blendPose(base, target, p / 0.18)
    if (p < 0.5) return target
    return blendPose(target, POSES.idle, (p - 0.5) / 0.5)
  }
  if (f.action === 'hurt' || f.action === 'stagger') {
    return blendPose(base, target, Math.min(1, p * 5))
  }
  if (f.action === 'dash') return target
  if (f.action === 'dead') return target
  return base
}

export function drawFighter(ctx, cam, f, time, opts = {}) {
  const s = cam.scale
  const palette = opts.palette || f.palette
  const ghost = opts.ghost || null
  const ghostColor = opts.ghostColor
  const alpha = opts.alpha ?? 1
  const flash = f.flash > 0 && !ghost

  const footX = cam.X(f.x)
  const footY = cam.Y(f.y)
  if (!Number.isFinite(footX) || !Number.isFinite(footY)) return
  const d = f.facing >= 0 ? 1 : -1
  const pose = opts.pose || actionPose(f)
  const t = f.animTime || time
  const moving = f.grounded && Math.abs(f.vx) > 8
  const walk = moving ? Math.sin(t * 13) * clamp(Math.abs(f.vx) / 80, 0, 1) : 0
  const bob = f.grounded ? (moving ? Math.abs(Math.sin(t * 13)) * 0.9 : Math.sin(t * 2.1) * 0.7) : -0.7
  const lean = pose.lean + clamp(f.vx / 190, -1.4, 1.4)
  const crouch = pose.crouch

  const anchorX = Math.round(footX)
  const anchorY = Math.round(footY)

  const color = key => {
    if (ghostColor) return ghostColor
    if (flash) return '#ffffff'
    return palette[key]
  }

  const boots = color('cloakDark')
  const cloak = color('cloak')
  const cloakLight = color('cloakLight')
  const trim = color('trim')
  const accent = color('accent')
  const blade = color('blade')
  const glow = color('glow')
  const eye = color('eye')
  const metal = color('metal')

  ctx.save()
  ctx.globalAlpha = alpha
  if (ghost) {
    ctx.save()
    ctx.globalCompositeOperation = 'lighter'
  }

  const L = (x, y) => anchorX + x * d * s
  const V = (y) => anchorY + (y - crouch) * s

  // contact shadow
  if (!ghost && f.grounded) {
    ctx.globalAlpha = alpha * 0.4
    ctx.fillStyle = '#000000'
    ctx.beginPath()
    ctx.ellipse(anchorX, anchorY + 1, 8 * s, 2.2 * s, 0, 0, TAU)
    ctx.fill()
    ctx.globalAlpha = alpha * 0.22
    ctx.fillStyle = glow
    ctx.beginPath()
    ctx.ellipse(anchorX, anchorY + 1, 7 * s, 1.6 * s, 0, 0, TAU)
    ctx.fill()
    ctx.globalAlpha = alpha
  }

  // back arm
  const shoulder = [0, -24.5]
  const backHand = [-4.5 + walk * 1.4, -18 + bob]
  pline(ctx, L(shoulder[0], V(shoulder[1])), L(-2 + walk, V(-21)), Math.max(1.4, 2.1 * s), color('cloakDark'))
  pline(ctx, L(-2 + walk, V(-21)), L(backHand[0], V(backHand[1])), Math.max(1.3, 1.9 * s), color('cloakDark'))

  // legs
  const hipY = -13.5
  const air = !f.grounded
  const legSpread = air ? 2.2 : 2.5
  const fFoot = air ? [4.4, -3.5] : [legSpread + walk * 4.2, 0]
  const bFoot = air ? [-3.6, -2] : [-legSpread - walk * 4.2, 0]
  const kneeF = air ? [4.8, -8] : [legSpread * 0.9 + walk * 2.4, -7]
  const kneeB = air ? [-4, -7] : [-legSpread * 0.9 - walk * 2.4, -6.5]
  pline(ctx, L(0, V(hipY)), L(kneeB[0], V(kneeB[1])), Math.max(1.5, 2.3 * s), color('cloakDark'))
  pline(ctx, L(kneeB[0], V(kneeB[1])), L(bFoot[0], V(bFoot[1])), Math.max(1.4, 2.1 * s), color('cloakDark'))
  pline(ctx, L(-1, V(hipY)), L(kneeF[0], V(kneeF[1])), Math.max(1.6, 2.5 * s), cloak)
  pline(ctx, L(kneeF[0], V(kneeF[1])), L(fFoot[0], V(fFoot[1])), Math.max(1.5, 2.3 * s), cloak)
  // boots
  px(ctx, L(fFoot[0] - 0.5, V(fFoot[1] - 1.4)), 3.4 * s, 1.5 * s, boots)
  px(ctx, L(bFoot[0] - 0.5, V(bFoot[1] - 1.4)), 3.2 * s, 1.4 * s, boots)

  // cloak body — pixel rows
  const baseY = -25
  const hemY = -7 - crouch * 0.6
  const sway = Math.sin(t * 2.7) * 0.7
  for (let y = baseY; y <= hemY; y += 0.9) {
    const p = (y - baseY) / (hemY - baseY)
    const half = (3.6 + p * 3.2 + (air ? p * 1.2 : 0))
    const cx = -p * 0.8 + lean + sway * p
    px(ctx, L(cx - half, V(y)), half * 2 * s, Math.max(1, 1.15 * s), cloak)
    if (p < 0.55) px(ctx, L(cx - half, V(y)), 1.2 * s, Math.max(1, 1.15 * s), cloakLight)
    // torn hem
    if (p > 0.86 && Math.abs(Math.sin(y * 2.3 + t)) > 0.55) {
      px(ctx, L(cx + half * 0.3, V(y + 0.8)), 1.5 * s, 1.2 * s, cloak)
    }
  }
  // chest trim
  px(ctx, L(-1.1 + lean * 0.3, V(-22)), 1.1 * s, 7 * s, trim)
  px(ctx, L(-1.1 + lean * 0.3, V(-15.5)), 2.4 * s, 1.1 * s, trim)

  // scarf
  const scarfSegments = 5
  for (let i = 0; i < scarfSegments; i++) {
    const sx = -3 - i * 1.5 + Math.sin(t * 4 + i * 0.8) * 0.6 - (moving ? 1.5 : 0)
    const sy = -26 + i * 0.55 + Math.sin(t * 3.2 + i * 0.9) * 1.1
    ctx.globalAlpha = alpha * (0.75 - i * 0.11)
    px(ctx, L(sx, V(sy)), (2.2 - i * 0.25) * s, 1.3 * s, i % 2 ? accent : trim)
  }
  ctx.globalAlpha = alpha

  // hood / head
  const headCenter = -30.5 + bob
  for (let i = 0; i < 9; i++) {
    const yy = headCenter - 4.2 + i * 0.95
    const p = i / 8
    const half = 1.2 + Math.sin(Math.min(1, p * 1.2) * Math.PI * 0.62) * 3.4
    const cx = -1.4 + p * 0.2
    px(ctx, L(cx - half, V(yy)), half * 2 * s, Math.max(1, 1.05 * s), cloakLight)
  }
  // hood ridge + point
  px(ctx, L(-3.4, V(headCenter - 3.2)), 3.4 * s, 1.2 * s, cloak)
  px(ctx, L(-4.6, V(headCenter - 2.2)), 1.8 * s, 1.2 * s, cloak)
  // face void
  px(ctx, L(0.2, V(headCenter - 2.2)), 3.4 * s, 3.3 * s, '#05050c')
  // eyes
  const blink = Math.sin(t * 0.9 + f.seed * 7) > 0.985
  if (!blink && !ghost) {
    px(ctx, L(1.4, V(headCenter - 1.2)), Math.max(1, 1.1 * s), Math.max(1, 0.8 * s), eye)
    if (f.enraged) {
      ctx.save()
      ctx.globalCompositeOperation = 'lighter'
      glowDot(ctx, L(2, V(headCenter - 1.1)), 2.6 * s, glow, 0.4)
      ctx.restore()
    }
  }
  // hood cowl
  px(ctx, L(-3, V(-25.8)), 6 * s, 1.4 * s, cloak)
  px(ctx, L(-2, V(-26.8)), 4.4 * s, 1 * s, cloakLight)

  // front arm
  const hand = pose.hand
  const handWX = hand[0] + lean * 0.5
  const handWY = hand[1] + bob * 0.5
  const elbow = [(shoulder[0] + handWX) / 2 + 2.4, (shoulder[1] + handWY) / 2 + 1.6]
  pline(ctx, L(shoulder[0] + 1, V(shoulder[1] + bob * 0.5)), L(elbow[0], V(elbow[1])), Math.max(1.7, 2.6 * s), cloakLight)
  pline(ctx, L(elbow[0], V(elbow[1])), L(handWX, V(handWY)), Math.max(1.5, 2.3 * s), cloakLight)
  // hand
  px(ctx, L(handWX - 0.8, V(handWY - 0.8)), 2 * s, 2 * s, metal)

  // blade
  const bladeLen = f.action === 'heavy' ? 21 : 18
  const ba = pose.blade + (f.action === 'hurt' || f.action === 'stagger' ? Math.sin(t * 20) * 0.15 : 0)
  const bx = handWX
  const by = handWY
  const tipX = bx + Math.cos(ba) * bladeLen
  const tipY = by + Math.sin(ba) * bladeLen
  const hiltX = bx - Math.cos(ba) * 2.2
  const hiltY = by - Math.sin(ba) * 2.2

  if (ghost) {
    pline(ctx, L(hiltX, V(hiltY)), L(tipX, V(tipY)), Math.max(1, 2.2 * s), ghostColor)
  } else {
    // glow
    ctx.save()
    ctx.globalCompositeOperation = 'lighter'
    ctx.globalAlpha = alpha * (0.16 + (f.charge || 0) * 0.2)
    pline(ctx, L(hiltX, V(hiltY)), L(tipX, V(tipY)), 5 * s, glow)
    ctx.globalAlpha = alpha * 0.3
    pline(ctx, L(hiltX, V(hiltY)), L(tipX, V(tipY)), 3 * s, trim)
    ctx.restore()
    ctx.globalAlpha = alpha
    // core
    pline(ctx, L(hiltX, V(hiltY)), L(tipX, V(tipY)), Math.max(1.2, 2 * s), flash ? '#ffffff' : blade)
    px(ctx, L(hiltX - 1.4, V(hiltY - 1.4)), 2.8 * s, 2.8 * s, metal)
    px(ctx, L(hiltX - 2.8, V(hiltY - 0.4)), 1.4 * s, 1 * s, trim)
    // tip glint
    ctx.save()
    ctx.globalCompositeOperation = 'lighter'
    glowDot(ctx, L(tipX, V(tipY)), 2.4 * s, glow, 0.55)
    ctx.restore()
  }

  // parry ward
  if (f.action === 'parry' && f.parryActive) {
    ctx.save()
    ctx.globalCompositeOperation = 'lighter'
    ctx.globalAlpha = alpha * 0.8
    ctx.strokeStyle = trim
    ctx.lineWidth = Math.max(1, 1.6 * s)
    ctx.beginPath()
    ctx.arc(L(5, V(-20)), 12 * s, -1.1, 1.1)
    ctx.stroke()
    ctx.globalAlpha = alpha * 0.32
    ctx.lineWidth = Math.max(2, 4 * s)
    ctx.stroke()
    for (let i = 0; i < 5; i++) {
      const a = -1 + i * 0.5
      const rx = 5 + Math.cos(a) * 12
      const ry = -20 + Math.sin(a) * 12
      px(ctx, L(rx - 0.5, V(ry - 0.5)), 1.4 * s, 1.4 * s, i % 2 ? '#ffffff' : accent)
    }
    ctx.restore()
    ctx.globalAlpha = alpha
  }

  // cast circle
  if (f.action === 'cast') {
    const p = clamp(f.actionT / (f.actionDur || 0.5), 0, 1)
    const cx = handWX + 2
    const cy = handWY - 1
    const r = (3 + p * 6) * s
    ctx.save()
    ctx.globalCompositeOperation = 'lighter'
    ctx.globalAlpha = alpha * Math.min(1, p * 2)
    ctx.strokeStyle = f.castColor || glow
    ctx.lineWidth = Math.max(1, 1.2 * s)
    ctx.beginPath()
    ctx.arc(L(cx, V(cy)), r, 0, TAU)
    ctx.stroke()
    ctx.globalAlpha *= 0.6
    ctx.beginPath()
    ctx.arc(L(cx, V(cy)), r * 0.6, 0, TAU)
    ctx.stroke()
    for (let i = 0; i < 4; i++) {
      const a = time * 5 + (i / 4) * TAU
      px(ctx, L(cx + Math.cos(a) * r / s, V(cy + Math.sin(a) * r / s)), 1.4 * s, 1.4 * s, '#ffffff')
    }
    ctx.restore()
    ctx.globalAlpha = alpha
  }

  // guard sparkle
  if (f.action === 'guard') {
    ctx.save()
    ctx.globalCompositeOperation = 'lighter'
    ctx.globalAlpha = alpha * (0.22 + 0.1 * Math.sin(t * 6))
    ctx.fillStyle = trim
    ctx.beginPath()
    ctx.arc(L(7, V(-20)), 14 * s, -1.2, 1.2)
    ctx.lineWidth = 2 * s
    ctx.strokeStyle = trim
    ctx.stroke()
    ctx.restore()
  }

  // status frost
  if (f.slowT > 0) {
    ctx.save()
    ctx.globalCompositeOperation = 'lighter'
    ctx.globalAlpha = alpha * 0.22
    for (let i = 0; i < 3; i++) {
      const a = time * 1.4 + i * 2.1
      px(ctx, L(Math.cos(a) * 6, V(-18 + Math.sin(a) * 7)), 1.4 * s, 1.4 * s, '#9fe8ff')
    }
    ctx.restore()
  }

  // boss aura
  if (f.enraged && !ghost) {
    ctx.save()
    ctx.globalCompositeOperation = 'lighter'
    ctx.globalAlpha = alpha * (0.22 + 0.1 * Math.sin(time * 4))
    ctx.strokeStyle = glow
    ctx.lineWidth = Math.max(1, 1.2 * s)
    ctx.beginPath()
    ctx.ellipse(anchorX, anchorY, 14 * s, 3.4 * s, 0, 0, TAU)
    ctx.stroke()
    for (let i = 0; i < 4; i++) {
      const a = time * 1.8 + (i / 4) * TAU
      glowDot(ctx, anchorX + Math.cos(a) * 12 * s, anchorY - 4 * s + Math.sin(a) * 9 * s, 1.5 * s, glow, 0.5)
    }
    ctx.restore()
  }

  if (ghost) ctx.restore()
  ctx.restore()
}

export function drawGhost(ctx, cam, snapshot, color, alpha) {
  drawFighter(ctx, cam, snapshot, snapshot.animTime || 0, {
    ghost: true,
    ghostColor: color,
    alpha,
    pose: snapshot.pose,
    palette: snapshot.palette,
  })
}

export function drawBladeTrail(ctx, cam, trail, color, alpha = 1) {
  if (!trail || trail.length < 2) return
  ctx.save()
  ctx.globalCompositeOperation = 'lighter'
  for (let i = 0; i < trail.length; i++) {
    const p = trail[i]
    const a = (i / trail.length) * alpha * 0.7
    if (a <= 0.01) continue
    ctx.globalAlpha = a
    ctx.fillStyle = color
    const size = Math.max(1, (0.8 + (i / trail.length) * 1.8) * cam.scale)
    ctx.fillRect(cam.X(p.x) - size / 2, cam.Y(p.y) - size / 2, size, size)
  }
  ctx.restore()
}

// ------------------------------------------------------------- helpers

export function drawVignette(ctx, width, height) {
  const g = ctx.createRadialGradient(width / 2, height / 2, Math.min(width, height) * 0.35, width / 2, height / 2, Math.max(width, height) * 0.72)
  g.addColorStop(0, 'rgba(0,0,0,0)')
  g.addColorStop(1, 'rgba(0,0,0,0.55)')
  ctx.fillStyle = g
  ctx.fillRect(0, 0, width, height)
}

export function drawConfetti(ctx, cam, time, palette) {
  ctx.save()
  ctx.globalCompositeOperation = 'lighter'
  for (let i = 0; i < 14; i++) {
    const x = (Math.sin(time * 0.4 + i * 1.7) * 0.5 + 0.5) * cam.width
    const y = (time * (8 + i * 0.7) + i * 47) % cam.height
    ctx.globalAlpha = 0.12 + 0.16 * Math.sin(time + i)
    const size = i % 3 === 0 ? 2 : 1
    ctx.fillStyle = i % 4 === 0 ? '#ffffff' : palette.trim
    ctx.fillRect(x, y, size, size)
  }
  ctx.restore()
}

export function hexA(hex, alpha) {
  if (!hex || !hex.startsWith('#')) return `rgba(150,140,255,${alpha})`
  let h = hex.slice(1)
  if (h.length === 3) h = h.split('').map(c => c + c).join('')
  const n = parseInt(h, 16)
  const r = (n >> 16) & 255
  const g = (n >> 8) & 255
  const b = n & 255
  return `rgba(${r},${g},${b},${alpha})`
}

const ARENA_HALF = 176
const ARENA_DEPTH = 26

import {
  ARENA, PHYSICS, PARRY, DASH, ATTACKS, SPELLS, SPELL_ORDER, COMBO_WINDOW,
} from './config.js'

const clamp = (v, a, b) => Math.max(a, Math.min(b, v))
const rand = (a, b) => a + Math.random() * (b - a)
const sign = v => (v >= 0 ? 1 : -1)

export class Fighter {
  constructor(options) {
    const {
      name = 'DUELIST', title = '', palette, x = 0, facing = 1,
      maxHp = 100, maxMana = 60, isPlayer = false,
      stats = null, stage = null, difficulty = null, spells = ['ember'],
    } = options
    this.name = name
    this.title = title
    this.palette = palette
    this.isPlayer = isPlayer
    this.stats = stats
    this.stage = stage
    this.difficulty = difficulty
    this.spells = spells.slice()
    this.x = x
    this.y = 0
    this.vx = 0
    this.vy = 0
    this.facing = facing
    this.grounded = true
    this.maxHp = maxHp
    this.hp = maxHp
    this.maxMana = maxMana
    this.mana = maxMana
    this.hpGhost = maxHp
    this.action = 'idle'
    this.actionT = 0
    this.actionDur = 0
    this.attackKind = null
    this.attackData = null
    this.attackHit = false
    this.comboStep = 0
    this.comboQueue = false
    this.comboTimer = 0
    this.parryActive = false
    this.parryCd = 0
    this.dashCd = 0
    this.spellCd = Object.fromEntries(SPELL_ORDER.map(id => [id, 0]))
    this.hurtT = 0
    this.staggerT = 0
    this.stunT = 0
    this.slowT = 0
    this.burnT = 0
    this.burnTick = 0.5
    this.invuln = 0
    this.flash = 0
    this.charge = 0
    this.animTime = 0
    this.seed = Math.random() * 10
    this.bladeTrail = []
    this.ghostTimer = 0
    this.dead = false
    this.deathT = 0
    this.enraged = false
    this.phase = 1
    this.damageMult = 1
    this.damageTaken = 1
    this.moveSpeed = PHYSICS.moveSpeed
    this.parryWindow = PARRY.active
    this.parryCooldown = PARRY.cooldown
    this.dashCooldown = DASH.cooldown
    this.siphon = 0
    this.castSpellId = null
    this.castColor = null
    this.castReleased = false
    this.ai = {
      timer: rand(0.2, 0.7), guardT: 0, reacted: false, parryDelay: 0, feint: 0, dashCd: 0,
    }
    this.lastHitBy = null
    this.comboHits = 0
    this.guardFlash = 0

    if (isPlayer && stats) {
      this.maxHp = stats.maxHp
      this.hp = stats.maxHp
      this.hpGhost = stats.maxHp
      this.maxMana = stats.maxMana
      this.mana = stats.maxMana
      this.parryWindow = stats.parryWindow
      this.parryCooldown = stats.parryCooldown
      this.dashCooldown = stats.dashCooldown
      this.moveSpeed = PHYSICS.moveSpeed * stats.speed
      this.damageMult = stats.melee
      this.spellPower = stats.arcane
      this.damageTaken = stats.resist
      this.siphon = stats.siphon
    } else if (stage) {
      const d = difficulty || { dmg: 1, hp: 1, reaction: 1, windup: 1, cooldown: 1 }
      this.maxHp = Math.round(stage.hp * d.hp)
      this.hp = this.maxHp
      this.hpGhost = this.maxHp
      this.maxMana = 100
      this.mana = 100
      this.moveSpeed = PHYSICS.moveSpeed * (stage.speed || 1)
      this.damageMult = (stage.dmg || 1) * d.dmg
      this.spellPower = 1 + (stage.boss ? 0.18 : 0)
      this.parryChance = (stage.parryChance + d.parryChance) / 2
      this.reaction = d.reaction
      this.windupScale = d.windup
      this.spellCooldownScale = d.cooldown
      this.aggression = stage.aggression * (0.6 + d.aggression * 0.7)
      this.preferred = stage.preferred || 36
    }
  }

  get hpRatio() { return Math.max(0, this.hp) / this.maxHp }
  get manaRatio() { return Math.max(0, this.mana) / this.maxMana }

  get busy() {
    return ['strike1', 'strike2', 'strike3', 'heavy', 'parry', 'cast', 'dash', 'hurt', 'stagger', 'dead'].includes(this.action)
  }

  get canMove() {
    return !this.dead && ['idle', 'run', 'jump', 'guard'].includes(this.action) && this.staggerT <= 0 && this.stunT <= 0
  }

  canAct() {
    if (this.dead || this.staggerT > 0 || this.stunT > 0) return false
    if (['strike1', 'strike2', 'strike3', 'heavy'].includes(this.action)) {
      const d = this.attackData
      return d && this.actionT >= d.windup + d.active * 0.7
    }
    return ['idle', 'run', 'jump', 'guard', 'hurt'].includes(this.action)
  }

  faceToward(other) {
    if (!other || this.busy) return
    if (Math.abs(other.x - this.x) > 1) this.facing = sign(other.x - this.x)
  }

  startStrike(step = 1) {
    const key = `light${clamp(step, 1, 3)}`
    const base = ATTACKS[key]
    this.attackKind = key
    this.attackData = this.scaleAttack(base)
    this.action = `strike${clamp(step, 1, 3)}`
    this.actionT = 0
    this.actionDur = this.attackData.windup + this.attackData.active + this.attackData.recover
    this.attackHit = false
    this.comboQueue = false
    this.comboStep = step
    this.vx += this.facing * (step === 3 ? 46 : 30)
    this.charge = 0.25
    return { type: 'swing', heavy: false }
  }

  startHeavy() {
    this.attackKind = 'heavy'
    this.attackData = this.scaleAttack(ATTACKS.heavy)
    this.action = 'heavy'
    this.actionT = 0
    this.actionDur = this.attackData.windup + this.attackData.active + this.attackData.recover
    this.attackHit = false
    this.comboQueue = false
    this.comboStep = 0
    this.vx += this.facing * 40
    this.charge = 0.5
    return { type: 'swingHeavy', heavy: true }
  }

  scaleAttack(base) {
    const copy = { ...base }
    if (!this.isPlayer) {
      copy.windup *= this.windupScale || 1
      copy.recover *= 0.92
    }
    return copy
  }

  tryStrike() {
    if (!this.canAct()) return null
    if (['strike1', 'strike2', 'strike3'].includes(this.action)) {
      if (this.comboStep < 3 && !this.comboQueue && this.comboTimer > 0) {
        this.comboQueue = true
        return { type: 'queue' }
      }
      return null
    }
    return this.startStrike(1)
  }

  tryHeavy() {
    if (!this.canAct()) return null
    if (['strike1', 'strike2', 'strike3'].includes(this.action)) return null
    return this.startHeavy()
  }

  tryParry() {
    if (!this.canAct() || this.parryCd > 0) return null
    this.action = 'parry'
    this.actionT = 0
    this.actionDur = this.parryWindow + 0.26
    this.parryActive = true
    this.parryCd = this.parryCooldown
    this.vx *= 0.3
    return { type: 'parry' }
  }

  tryDash(axis = 0) {
    if (!this.canAct() || this.dashCd > 0 || !this.grounded) return null
    const dir = axis || this.facing
    this.facing = dir
    this.action = 'dash'
    this.actionT = 0
    this.actionDur = DASH.duration
    this.dashCd = this.dashCooldown
    this.vx = dir * DASH.speed
    this.vy = 0
    this.invuln = Math.max(this.invuln, DASH.iframes)
    this.ghostTimer = 0
    return { type: 'dash', dir }
  }

  tryCast(id, game) {
    if (this.dead) return null
    if (!SPELLS[id]) return null
    if (!this.spells.includes(id)) {
      if (this.isPlayer) game?.notice(`${SPELLS[id].name} unlocks at stage ${SPELLS[id].unlockStage}`, 'locked')
      return null
    }
    if (this.spellCd[id] > 0) return null
    if (this.isPlayer && this.mana < SPELLS[id].cost) {
      game?.notice('NOT ENOUGH MANA', 'mana')
      return null
    }
    if (!this.canAct()) return null
    if (!this.isPlayer) {
      if (this.spellCd[id] > 0) return null
    }
    this.action = 'cast'
    this.actionT = 0
    this.actionDur = 0.56
    this.castSpellId = id
    this.castReleased = false
    this.castColor = SPELLS[id].glow
    this.spellCd[id] = SPELLS[id].cooldown * (this.isPlayer ? 1 : this.spellCooldownScale || 1) * (this.enraged ? 0.7 : 1)
    if (this.isPlayer) this.mana -= SPELLS[id].cost
    this.vx *= 0.25
    return { type: 'castStart', spell: id }
  }

  releaseCast(game) {
    if (this.castReleased || !this.castSpellId) return
    this.castReleased = true
    game.castSpell(this, this.castSpellId)
  }

  isParryingFrom(attacker) {
    if (!this.parryActive) return false
    if (this.action !== 'parry') return false
    if (!attacker) return true
    const dir = sign(attacker.x - this.x)
    return dir === this.facing || Math.abs(attacker.x - this.x) < 4
  }

  onParry(attacker, game) {
    this.mana = Math.min(this.maxMana, this.mana + PARRY.manaGain)
    if (this.siphon > 0) {
      this.hp = Math.min(this.maxHp, this.hp + this.siphon)
      game?.fx.text(this.x, -40, `+${this.siphon}`, '#7cf7c4', { size: 8, life: 0.8 })
    }
    if (attacker) {
      attacker.staggerT = PARRY.stagger
      attacker.action = 'stagger'
      attacker.actionT = 0
      attacker.actionDur = PARRY.stagger
      attacker.vx = sign(attacker.x - this.x) * 80
      attacker.parryActive = false
      attacker.comboStep = 0
    }
  }

  takeHit(data, attacker, game) {
    if (this.dead) return 'dead'
    if (this.invuln > 0) return 'miss'
    const fromFront = attacker ? sign(attacker.x - this.x) === this.facing : true

    if (this.isParryingFrom(attacker)) {
      this.onParry(attacker, game)
      return 'parry'
    }

    if (this.action === 'guard' && fromFront) {
      if (data.guardBreak) {
        const dmg = data.dmg * attacker.damageMult * this.damageTaken * 0.55
        this.applyDamage(dmg, attacker)
        this.staggerT = 0.95
        this.action = 'stagger'
        this.actionT = 0
        this.actionDur = 0.95
        this.vx = sign(this.x - attacker.x) * 150
        this.action = 'stagger'
        return 'guardBreak'
      }
      const dmg = data.dmg * attacker.damageMult * this.damageTaken * 0.2
      this.applyDamage(dmg, attacker)
      this.vx = sign(this.x - attacker.x) * 35
      this.guardFlash = 0.18
      this.mana = Math.min(this.maxMana, this.mana + 3)
      return 'guard'
    }

    const variance = rand(0.94, 1.06)
    const dmg = data.dmg * attacker.damageMult * this.damageTaken * variance * (this.staggerT > 0 ? 1.2 : 1)
    this.applyDamage(dmg, attacker)
    this.flash = 0.14
    this.invuln = 0.09
    this.action = 'hurt'
    this.actionT = 0
    this.actionDur = data.dmg > 14 ? 0.38 : 0.26
    this.vx = sign(this.x - attacker.x) * (data.kb || 70)
    this.vy = Math.min(this.vy, -40)
    this.grounded = false
    this.parryActive = false
    this.comboStep = 0
    this.castReleased = true
    return 'hit'
  }

  applyDamage(amount, attacker) {
    const dmg = Math.max(0.5, amount)
    this.hp = Math.max(0, this.hp - dmg)
    this.lastHitBy = attacker
    this.hitFlashAmount = dmg
    if (this.hp <= 0) this.die()
    return dmg
  }

  die() {
    if (this.dead) return
    this.dead = true
    this.action = 'dead'
    this.actionT = 0
    this.actionDur = 1.2
    this.vx = -this.facing * 40
    this.vy = -120
    this.grounded = false
    this.parryActive = false
  }

  update(dt, ctrl, game) {
    if (this.dead) {
      this.animTime += dt
      this.deathT += dt
      this.updatePhysics(dt, 0, true)
      return
    }
    this.animTime += dt
    this.flash = Math.max(0, this.flash - dt)
    this.invuln = Math.max(0, this.invuln - dt)
    this.parryCd = Math.max(0, this.parryCd - dt)
    this.dashCd = Math.max(0, this.dashCd - dt)
    this.guardFlash = Math.max(0, this.guardFlash - dt)
    this.charge = Math.max(0, this.charge - dt * 2.5)
    this.comboTimer = Math.max(0, this.comboTimer - dt)
    this.hpGhost += (this.hp - this.hpGhost) * Math.min(1, dt * 4.5)
    for (const id of Object.keys(this.spellCd)) this.spellCd[id] = Math.max(0, this.spellCd[id] - dt)

    if (this.slowT > 0) this.slowT = Math.max(0, this.slowT - dt)
    if (this.burnT > 0) {
      this.burnT -= dt
      this.burnTick -= dt
      if (this.burnTick <= 0) {
        this.burnTick = 0.45
        this.applyDamage(1.4, this.lastHitBy)
        game?.fx.burst(this.x, rand(-24, -6), { count: 3, colors: ['#ff8a3c', '#ffd08a'], speed: 18, gravity: -45, life: 0.5, size: 1.4 })
        game?.fx.text(this.x + rand(-8, 8), -34, '1', '#ff9a3c', { size: 6, life: 0.5 })
      }
    }
    if (this.staggerT > 0) this.staggerT = Math.max(0, this.staggerT - dt)
    if (this.stunT > 0) this.stunT = Math.max(0, this.stunT - dt)

    if (this.isPlayer) {
      this.mana = Math.min(this.maxMana, this.mana + (3.4 + (this.dead ? 0 : 0.6)) * dt)
    }

    // action lifecycle
    this.actionT += dt
    this.parryActive = this.action === 'parry' && this.actionT < this.parryWindow
    if (this.action === 'cast' && !this.castReleased && this.actionT >= 0.32) {
      this.releaseCast(game)
    }
    if (this.staggerT > 0 && this.action !== 'stagger') {
      this.action = 'stagger'
      this.actionT = 0
      this.actionDur = this.staggerT
    }
    if (this.stunT > 0 && this.action !== 'stagger') {
      // stunned: brief flinch, still can be hit
      if (!this.busy) {
        this.action = 'hurt'
        this.actionT = 0
        this.actionDur = this.stunT
      }
    }

    if (['strike1', 'strike2', 'strike3', 'heavy'].includes(this.action)) {
      this.updateAttack(dt, game)
      this.updatePhysics(dt, 0, true)
      return
    }
    if (this.action === 'parry') {
      if (this.actionT >= this.actionDur) {
        this.action = 'idle'
        this.parryActive = false
      }
      this.updatePhysics(dt, 0, true)
      return
    }
    if (this.action === 'cast') {
      if (this.actionT >= this.actionDur) this.action = 'idle'
      this.updatePhysics(dt, 0, true)
      return
    }
    if (this.action === 'dash') {
      if (this.actionT >= this.actionDur) {
        this.action = 'idle'
        this.vx *= 0.3
      }
      this.ghostTimer -= dt
      if (this.ghostTimer <= 0 && game) {
        this.ghostTimer = 0.025
        game.pushGhost(this)
      }
      this.updatePhysics(dt, 0, true)
      return
    }
    if (this.action === 'hurt' || this.action === 'stagger') {
      if (this.actionT >= this.actionDur) {
        this.action = 'idle'
        this.vx *= 0.4
      }
      this.updatePhysics(dt, 0, true)
      return
    }

    // free movement
    const axis = this.stunT > 0 ? 0 : ctrl.axis
    if (this.parryCd > 0) this.parryActive = false

    if (ctrl.parry && this.tryParry()) {
      game?.onAction(this, 'parry')
      this.updatePhysics(dt, 0, true)
      return
    }
    if (ctrl.dash) {
      const res = this.tryDash(axis)
      if (res) {
        game?.onAction(this, 'dash', res)
        this.updatePhysics(dt, 0, true)
        return
      }
    }
    if (ctrl.strike) {
      const res = this.tryStrike()
      if (res) {
        game?.onAction(this, res.type === 'queue' ? 'queue' : 'strike')
        if (res.type !== 'queue') this.updatePhysics(dt, 0, true)
        return
      }
    }
    if (ctrl.heavy) {
      const res = this.tryHeavy()
      if (res) {
        game?.onAction(this, 'heavy')
        this.updatePhysics(dt, 0, true)
        return
      }
    }
    if (ctrl.spell) {
      const res = this.tryCast(ctrl.spell, game)
      if (res) {
        game?.onAction(this, 'cast', res)
        this.updatePhysics(dt, 0, true)
        return
      }
    }
    if (ctrl.jump && this.grounded && this.canMove) {
      this.vy = PHYSICS.jumpVel
      this.grounded = false
      this.action = 'jump'
      game?.onAction(this, 'jump')
    }

    if (ctrl.guard && this.grounded && this.canMove && !ctrl.jump) {
      this.action = 'guard'
      this.vx *= 0.6
      this.updatePhysics(dt, 0, true)
      return
    }
    if (this.action === 'guard' && !ctrl.guard) this.action = 'idle'

    if (this.grounded) {
      if (axis !== 0) {
        this.vx += axis * PHYSICS.groundAccel * dt
        this.vx = clamp(this.vx, -this.moveSpeed, this.moveSpeed)
        this.action = 'run'
        this.facing = axis
      } else {
        this.vx -= this.vx * Math.min(1, PHYSICS.friction * dt / Math.max(1, Math.abs(this.vx) + 30))
        if (Math.abs(this.vx) < 3) this.vx = 0
        this.action = 'idle'
      }
    } else {
      if (axis !== 0) this.vx += axis * PHYSICS.airAccel * dt
      this.vx = clamp(this.vx, -this.moveSpeed * 1.25, this.moveSpeed * 1.25)
    }
    this.updatePhysics(dt, axis, false)
  }

  updateAttack(dt, game) {
    const d = this.attackData
    if (!d) { this.action = 'idle'; return }
    // active hit sampling is handled by game; here only pose/queue
    if (this.actionT >= this.actionDur) {
      if (this.comboQueue && this.comboStep > 0 && this.comboStep < 3) {
        this.startStrike(this.comboStep + 1)
        game?.onAction(this, 'strike')
      } else {
        this.action = 'idle'
        this.comboTimer = COMBO_WINDOW
        this.comboStep = 0
        this.comboQueue = false
        this.charge = 0
      }
    }
  }

  updatePhysics(dt, axis, locked) {
    if (!this.grounded) {
      this.vy = Math.min(PHYSICS.maxFall, this.vy + PHYSICS.gravity * dt)
      this.y += this.vy * dt
      if (this.y >= 0) {
        this.y = 0
        this.vy = 0
        this.grounded = true
        this.action = this.action === 'jump' ? 'idle' : this.action
        this.onLand?.()
      }
    }
    if (locked) {
      if (this.grounded && this.action !== 'dash') {
        this.vx -= this.vx * Math.min(1, dt * 7)
      }
    }
    this.x += this.vx * dt
    if (this.x < ARENA.minX) { this.x = ARENA.minX; this.vx = Math.max(0, this.vx) }
    if (this.x > ARENA.maxX) { this.x = ARENA.maxX; this.vx = Math.min(0, this.vx) }
  }

  // ------------------------------------------------------------- enemy AI
  updateAI(dt, game) {
    if (this.dead) return { axis: 0 }
    const player = game.player
    if (!player) return { axis: 0 }
    const dx = player.x - this.x
    const dist = Math.abs(dx)
    if (!this.busy) this.facing = sign(dx)

    this.ai.timer -= dt
    this.ai.guardT = Math.max(0, this.ai.guardT - dt)

    // parry reaction to telegraphed swings
    const playerSwing = player.action.startsWith('strike') || player.action === 'heavy'
    if (playerSwing && player.attackData && dist < 58 && this.grounded && this.parryCd <= 0) {
      const windupLeft = player.attackData.windup - player.actionT
      if (windupLeft > 0 && !this.ai.reacted) {
        this.ai.reacted = true
        this.ai.parryDelay = Math.max(0.02, 0.07 * this.reaction + rand(0, 0.05))
      }
    }
    if (this.ai.reacted) {
      this.ai.parryDelay -= dt
      if (this.ai.parryDelay <= 0) {
        this.ai.reacted = false
        const chance = (this.parryChance || 0.1) * (this.enraged ? 1.2 : 1)
        if (Math.random() < chance && dist < 62 && this.canAct()) {
          const res = this.tryParry()
          if (res) {
            game.onAction(this, 'parry')
            return { axis: 0 }
          }
        }
      }
      if (!playerSwing) this.ai.reacted = false
    }

    // react to projectiles by parrying / dashing
    if (this.parryCd <= 0 && this.canAct()) {
      for (const p of game.projectiles) {
        if (p.owner === this) continue
        const towards = sign(p.x - this.x) === sign(-p.vx) && Math.abs(p.x - this.x) < 54
        if (!towards) continue
        if (Math.random() < 0.035 * (this.reaction ? 1 / this.reaction : 1)) {
          const res = this.tryParry()
          if (res) { game.onAction(this, 'parry'); return { axis: 0 } }
        }
        if (this.dashCd <= 0 && Math.abs(p.x - this.x) < 26 && Math.random() < 0.05) {
          const res = this.tryDash(-sign(p.vx))
          if (res) { game.onAction(this, 'dash', res); return { axis: 0 } }
        }
      }
    }

    if (!this.canAct()) return { axis: 0, guard: this.ai.guardT > 0 }

    // choice
    if (this.ai.timer <= 0) {
      this.ai.timer = (0.22 + Math.random() * 0.38) * (this.reaction || 1)
      if (dist < 50) {
        const roll = Math.random()
        if (roll < this.aggression) {
          if (Math.random() < 0.22) {
            const res = this.tryHeavy()
            if (res) { game.onAction(this, 'heavy'); return { axis: 0 } }
          } else {
            const res = this.tryStrike()
            if (res) { game.onAction(this, 'strike'); return { axis: 0 } }
          }
        } else if (roll < this.aggression + 0.18) {
          this.ai.guardT = 0.25 + Math.random() * 0.4
          return { axis: 0, guard: true }
        } else if (roll < this.aggression + 0.42) {
          const res = this.tryParry()
          if (res) { game.onAction(this, 'parry'); return { axis: 0 } }
        }
      } else if (dist > 56) {
        if (this.spells.length && Math.random() < 0.5) {
          const ready = this.spells.filter(id => this.spellCd[id] <= 0)
          if (ready.length) {
            const id = ready[Math.floor(Math.random() * ready.length)]
            const res = this.tryCast(id, game)
            if (res) { game.onAction(this, 'cast', res); return { axis: 0 } }
          }
        }
        if (dist > 105 && this.dashCd <= 0 && Math.random() < 0.32) {
          const res = this.tryDash(sign(dx))
          if (res) { game.onAction(this, 'dash', res); return { axis: 0 } }
        }
      }
    }

    let axis = 0
    if (this.ai.guardT > 0) {
      return { axis: 0, guard: true }
    }
    if (dist > this.preferred + 7) axis = sign(dx)
    else if (dist < this.preferred - 22) axis = -sign(dx)
    else if (Math.random() < 0.008) axis = -sign(dx)
    return { axis, guard: false }
  }

  snapshot() {
    return {
      x: this.x, y: this.y, facing: this.facing, vx: this.vx, vy: this.vy,
      grounded: this.grounded, action: this.action, actionT: this.actionT,
      actionDur: this.actionDur, animTime: this.animTime, flash: 0,
      slowT: this.slowT, enraged: false, parryActive: this.parryActive,
      palette: this.palette, seed: this.seed, dead: false,
      pose: null,
    }
  }
}

