input.content:
@font-face {
  font-family: 'Silkscreen';
  src: url('assets/silkscreen-400.woff2') format('woff2');
  font-weight: 400;
  font-display: swap;
}
@font-face {
  font-family: 'Silkscreen';
  src: url('assets/silkscreen-700.woff2') format('woff2');
  font-weight: 700;
  font-display: swap;
}

:root {
  --bg: #05050b;
  --ink: #eeeaff;
  --dim: #a09cbd;
  --mute: #646080;
  --line: rgba(151, 143, 210, 0.22);
  --line-soft: rgba(151, 143, 210, 0.12);
  --panel: rgba(8, 8, 16, 0.7);
  --cyan: #6ee7ff;
  --cyan-dim: rgba(110, 231, 255, 0.5);
  --magenta: #ff6bd6;
  --gold: #ffe08a;
  --green: #7cf7c4;
  --danger: #ff5c78;
  --enemy: #ff6bd6;
  --pixel: 'Silkscreen', 'Courier New', monospace;
  --mono: 'DejaVu Sans Mono', 'SFMono-Regular', Consolas, 'Courier New', monospace;
}

* { box-sizing: border-box; }

html, body {
  margin: 0;
  padding: 0;
  height: 100%;
  background: var(--bg);
  color: var(--ink);
  overflow: hidden;
  overscroll-behavior: none;
}

body {
  font-family: var(--mono);
  font-size: 13px;
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
  -webkit-tap-highlight-color: transparent;
  user-select: none;
  touch-action: none;
}

button, input { font: inherit; color: inherit; }
button { cursor: pointer; }
::selection { background: var(--cyan); color: #041018; }

#app {
  position: relative;
  width: 100vw;
  height: 100vh;
  height: 100dvh;
  overflow: hidden;
  isolation: isolate;
  background: var(--bg);
}

#game {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
  image-rendering: pixelated;
  image-rendering: crisp-edges;
  background: var(--bg);
}

.fx-overlay {
  position: absolute;
  inset: 0;
  pointer-events: none;
  z-index: 3;
  background:
    radial-gradient(ellipse at 50% 42%, rgba(0, 0, 0, 0) 48%, rgba(3, 3, 8, 0.34) 100%),
    linear-gradient(180deg, rgba(8, 8, 20, 0.18), transparent 18%, transparent 82%, rgba(4, 4, 10, 0.25));
  mix-blend-mode: multiply;
}

.scanlines {
  position: absolute;
  inset: 0;
  pointer-events: none;
  z-index: 25;
  opacity: 0;
  transition: opacity 0.25s ease;
  background: repeating-linear-gradient(0deg, rgba(0, 0, 0, 0.35) 0 1px, rgba(0, 0, 0, 0) 1px 3px);
  mix-blend-mode: multiply;
}
.scanlines.on { opacity: 0.55; }

/* ------------------------------------------------------------------ type */

.display {
  margin: 0;
  font-family: var(--pixel);
  font-weight: 700;
  font-size: clamp(34px, 4.6vw, 66px);
  line-height: 0.95;
  letter-spacing: -0.02em;
  text-shadow: 0 0 30px rgba(110, 231, 255, 0.16);
}
.accent { color: var(--cyan); }

.eyebrow {
  display: flex;
  align-items: center;
  gap: 12px;
  margin: 0 0 18px;
  font-family: var(--pixel);
  font-size: 9px;
  letter-spacing: 0.26em;
  color: var(--dim);
}
.eyebrow-line {
  display: inline-block;
  width: 34px;
  height: 1px;
  background: linear-gradient(90deg, var(--cyan), transparent);
}

.body-copy {
  max-width: 54ch;
  margin: 0 0 18px;
  color: var(--dim);
  font-size: 12.5px;
  line-height: 1.8;
}

kbd {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 22px;
  height: 21px;
  padding: 0 5px;
  border: 1px solid var(--line);
  border-bottom-color: rgba(151, 143, 210, 0.4);
  background: rgba(255, 255, 255, 0.035);
  border-radius: 2px;
  font-family: var(--pixel);
  font-size: 8px;
  color: var(--ink);
  box-shadow: inset 0 -1px 0 rgba(0, 0, 0, 0.4);
}

.chip {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 4px 8px;
  border: 1px solid var(--line);
  font-family: var(--pixel);
  font-size: 8px;
  letter-spacing: 0.09em;
  color: var(--dim);
  background: rgba(255, 255, 255, 0.025);
}
.chip-diff {
  color: var(--cyan);
  border-color: rgba(110, 231, 255, 0.35);
  background: rgba(110, 231, 255, 0.07);
}

.pip {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 42px;
  padding: 3px 7px;
  margin-left: 10px;
  border: 1px solid rgba(110, 231, 255, 0.35);
  background: rgba(110, 231, 255, 0.08);
  color: var(--cyan);
  font-family: var(--pixel);
  font-size: 7px;
  letter-spacing: 0.08em;
  white-space: nowrap;
}
.pip.is-empty { color: var(--mute); border-color: var(--line); background: transparent; }

/* --------------------------------------------------------------- buttons */

.btn {
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  min-height: 44px;
  padding: 11px 16px;
  border: 1px solid var(--line);
  background: rgba(255, 255, 255, 0.025);
  color: var(--ink);
  font-family: var(--pixel);
  font-size: 10px;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  transition: background 0.16s ease, border-color 0.16s ease, color 0.16s ease, transform 0.16s ease;
  overflow: hidden;
}
.btn::after {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(110deg, transparent 30%, rgba(255, 255, 255, 0.09) 50%, transparent 70%);
  transform: translateX(-120%);
  transition: transform 0.5s ease;
  pointer-events: none;
}
.btn:hover::after { transform: translateX(120%); }
.btn:hover { border-color: rgba(110, 231, 255, 0.55); color: #fff; background: rgba(110, 231, 255, 0.06); }
.btn:active { transform: translateY(1px); }
.btn:focus-visible { outline: 1px solid var(--cyan); outline-offset: 3px; }

.btn-primary {
  border-color: var(--cyan);
  background: var(--cyan);
  color: #031018;
  font-weight: 700;
  box-shadow: 0 0 30px rgba(110, 231, 255, 0.14);
}
.btn-primary:hover { background: #a8f4ff; border-color: #a8f4ff; color: #031018; }
.btn-primary .btn-hint { color: rgba(3, 16, 24, 0.6); }
.btn-primary.is-disabled, .btn-primary:disabled {
  cursor: not-allowed;
  background: rgba(110, 231, 255, 0.08);
  border-color: var(--line);
  color: var(--mute);
  box-shadow: none;
}
.btn-primary.is-disabled:hover, .btn-primary:disabled:hover { background: rgba(110, 231, 255, 0.08); color: var(--mute); }

.btn-ghost { border-color: transparent; background: transparent; color: var(--dim); }
.btn-ghost:hover { background: rgba(255, 255, 255, 0.035); border-color: var(--line); }
.btn-danger { border-color: rgba(255, 92, 120, 0.45); color: var(--danger); background: rgba(255, 92, 120, 0.05); }
.btn-danger:hover { background: rgba(255, 92, 120, 0.12); border-color: var(--danger); color: #ffdbe2; }
.btn.is-disabled { opacity: 0.4; pointer-events: none; }
.btn-small { min-height: 32px; padding: 6px 12px; font-size: 8px; }

.menu { display: flex; flex-direction: column; gap: 7px; width: min(360px, 100%); margin-top: 26px; }
.btn-menu {
  justify-content: flex-start;
  min-height: 40px;
  padding: 10px 2px;
  border: none;
  border-bottom: 1px solid var(--line-soft);
  background: transparent;
  color: var(--dim);
  font-size: 9px;
}
.btn-menu:hover { padding-left: 10px; color: var(--cyan); background: linear-gradient(90deg, rgba(110, 231, 255, 0.06), transparent 70%); border-bottom-color: rgba(110, 231, 255, 0.25); }
.btn-menu .btn-aside { margin-left: auto; font-size: 7px; color: var(--mute); letter-spacing: 0.14em; }
.btn-menu .pip { margin-left: auto; }
.menu-row { display: grid; grid-template-columns: 1fr 1fr; gap: 7px; margin-top: 6px; }
.menu-row .btn { justify-content: center; font-size: 8px; }
.btn-main { font-weight: 700; }
.btn-hint { font-size: 7px; letter-spacing: 0.12em; opacity: 0.7; font-weight: 400; }

/* ---------------------------------------------------------------- screens */

#screens { position: absolute; inset: 0; z-index: 20; pointer-events: none; }

.screen {
  position: absolute;
  inset: 0;
  padding: clamp(18px, 2.6vw, 40px);
  display: flex;
  flex-direction: column;
  opacity: 0;
  visibility: hidden;
  pointer-events: none;
  transform: translateY(8px);
  transition: opacity 0.3s ease, transform 0.3s ease, visibility 0s linear 0.3s;
  overflow: hidden;
}
.screen.active {
  opacity: 1;
  visibility: visible;
  pointer-events: auto;
  transform: none;
  transition: opacity 0.3s ease, transform 0.3s ease, visibility 0s;
}
.screen::before {
  content: '';
  position: absolute;
  inset: 0;
  z-index: -1;
  background:
    radial-gradient(ellipse at 20% 0%, rgba(110, 231, 255, 0.055), transparent 55%),
    radial-gradient(ellipse at 85% 100%, rgba(255, 107, 214, 0.045), transparent 55%),
    linear-gradient(180deg, rgba(5, 5, 11, 0.965), rgba(7, 6, 14, 0.95));
  backdrop-filter: blur(14px);
}
.screen::after {
  content: '';
  position: absolute;
  inset: 0;
  z-index: -1;
  pointer-events: none;
  background-image:
    linear-gradient(rgba(140, 130, 220, 0.035) 1px, transparent 1px),
    linear-gradient(90deg, rgba(140, 130, 220, 0.035) 1px, transparent 1px);
  background-size: 88px 88px;
  mask-image: radial-gradient(ellipse at center, black 20%, transparent 78%);
  opacity: 0.7;
}

.back {
  border: 1px solid var(--line);
  background: transparent;
  color: var(--dim);
  font-family: var(--pixel);
  font-size: 8px;
  letter-spacing: 0.12em;
  padding: 8px 11px;
  transition: all 0.16s ease;
  flex: none;
}
.back:hover { color: var(--cyan); border-color: rgba(110, 231, 255, 0.5); background: rgba(110, 231, 255, 0.05); }

.panel-head {
  display: flex;
  align-items: center;
  gap: 18px;
  padding-bottom: 16px;
  border-bottom: 1px solid var(--line);
  flex: none;
}
.panel-kicker {
  margin: 0;
  font-family: var(--pixel);
  font-size: 9px;
  letter-spacing: 0.24em;
  color: var(--dim);
}
.panel-note { margin-left: auto; font-family: var(--pixel); font-size: 7px; letter-spacing: 0.12em; color: var(--mute); }

.gate-foot {
  display: flex;
  align-items: center;
  gap: 20px;
  padding-top: 18px;
  border-top: 1px solid var(--line);
  flex: none;
}
.gate-foot .btn-primary { margin-left: auto; min-width: 190px; }
.foot-note { color: var(--mute); font-size: 10px; line-height: 1.5; }

/* ------------------------------------------------------------------ title */

.title-screen {
  padding: clamp(18px, 2.8vw, 46px) clamp(20px, 4vw, 64px) clamp(16px, 2.4vw, 34px);
  background: transparent;
}
.title-screen::before {
  background:
    linear-gradient(90deg, rgba(4, 4, 10, 0.97) 0%, rgba(4, 4, 10, 0.85) 36%, rgba(4, 4, 10, 0.36) 64%, rgba(4, 4, 10, 0.05) 100%),
    linear-gradient(180deg, rgba(4, 4, 10, 0.7) 0%, transparent 18%, transparent 76%, rgba(4, 4, 10, 0.9) 100%);
  backdrop-filter: none;
}
.title-screen::after { display: none; }
.title-wash {
  position: absolute;
  inset: 0;
